import logging
import re
import zipfile

from taf.fdsw.rc.interfaces.exceptions import OperationFailure, RootDirNotFound, RequiredParamNotProvided
from taf.fdsw.rc.schemas.FDSW18SP.swm import (BtsInfo, SoftwareInventory,
                                              SoftwareUpdateStatus)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SoftwareManagement():

    SW_UPDATE_COMPLETED_STATUS = 1.0

    def __init__(self, client):
        self._client = client
        self.last_targetBD = None
        self.last_updated_sw_slot_id = None
        self.last_package = None

    def get_sw_inventory(self, sw_slot_id, timeout=10):
        sw_inventory = self._client.send(
            method="software.getInventory",
            parameters={"slotId": str(sw_slot_id)},
            timeout=timeout
        )
        if sw_inventory.status is False:
            error_msg = "Software inventory information is not available for slot ID {}, error {}"
            raise OperationFailure(error_msg.format(
                sw_slot_id,
                sw_inventory.error
            ))
        return SoftwareInventory.from_object_dict(data=sw_inventory.data)

    def get_active_sw_partition(self, timeout=10):
        all_sw_inventory = self.get_all_software_inventory()
        for slot in all_sw_inventory.software.slots:
            if slot.mode == 'Active':
                return slot.id

    def get_active_sw_version_name(self, max_slot_number=3, timeout=10):
        for slot_id in range(1, max_slot_number + 1):
            sw_inventory = self.get_sw_inventory(sw_slot_id=slot_id, timeout=timeout)
            if sw_inventory.active is True:
                return sw_inventory.sw_version

    def get_all_software_inventory(self, timeout=10):
        all_sw_inventory = self._client.send(
            method='fetch',
            parameters={},
            timeout=timeout
        )

        if all_sw_inventory.status is False:
            error_msg = "Running software inventory information is not available due to error {}"
            raise OperationFailure(error_msg.format(
                all_sw_inventory.error
            ))

        bts_info = BtsInfo.from_object_dict(all_sw_inventory.data)
        return bts_info

    def get_running_sw_version_name(self, timeout=10):
        sw_info = self.get_all_software_inventory(timeout=timeout)
        for slot in sw_info.software.slots:
            if slot.running is True:
                return slot.version

    def software_update(self, sw_pkg_path, activate=False, timeout=30, **kwargs):
        package = Package(sw_pkg_path)
        sw_slot_id = kwargs.get("sw_slot_id", None)
        if sw_slot_id is None:
            raise RequiredParamNotProvided("for this version of FDSW sw_slot_id parameter must be provided as kwarg")
        targetBD = self._get_targetBD_file(package)
        initialized_update_status = self.initialize_sw_update(targetBD, sw_slot_id, activate, timeout)
        self._upload_files_to_sw_update(package, initialized_update_status, timeout)
        self.last_targetBD = targetBD
        self.last_updated_sw_slot_id = sw_slot_id
        self.last_package = package

        logger.info('Software update succeeded.')

    def initialize_sw_update(self, targetBD, sw_slot_id, activate, timeout):
        logger.info('Starting software update on partition {}'.format(sw_slot_id))

        resp = self._client.send_file(
            method='software.startUpdating',
            parameters={"slotId": str(sw_slot_id), 'activate': activate},
            file_data=targetBD,
            timeout=timeout
        )
        self._check_sw_update_response(resp)
        targetBD_update_status = SoftwareUpdateStatus.from_object_dict(resp.data)
        logger.info('TargetBD file sent. Starting sending other files')
        return targetBD_update_status

    def _get_targetBD_file(self, package):
        files = package.find_filepaths('TargetBD')
        if len(files) == 1:
            return package.read_file(files[0])
        raise OperationFailure('Files with name TargetBD found: {}'.format(len(files)))

    def upload_a_file(self, next_file_name, package, timeout):
        file_data = package.read_file(next_file_name)
        resp = self._client.send_file(
            method='software.uploadFile',
            parameters={'filename': next_file_name},
            file_data=file_data,
            timeout=timeout
        )
        return resp

    def _upload_files_to_sw_update(self, package, update_status, timeout):
        logger.info('Update progress:')
        update_progress_bar = 0.1

        while update_status.next_filename is not None:

            next_file_name = update_status.next_filename
            resp = self.upload_a_file(next_file_name=next_file_name, package=package, timeout=timeout)
            self._check_sw_update_response(resp)
            update_status = SoftwareUpdateStatus.from_object_dict(resp.data)
            if self._check_if_sw_already_installed(update_status):
                break

            if update_status.update_progress > update_progress_bar:
                logger.info(round(update_status.update_progress, 1))
                update_progress_bar += 0.1

    @staticmethod
    def _check_if_sw_already_installed(update_status):
        if update_status.next_filename is None and update_status.update_progress == 0.0:
            error_msg = 'Requested SW Release is already installed on desired slot'
            logger.info(error_msg)
            return True
        return False

    @staticmethod
    def _check_sw_update_response(resp):
        if resp.status is False:
            error_msg = 'Software update failed: {}'.format(resp.error)
            raise OperationFailure(error_msg)

    def cancel_software_update(self, timeout=10):
        resp = self._client.send(
            method='software.stopUpdating',
            timeout=timeout,
            parameters={}
        )
        if resp.status is False:
            raise OperationFailure(resp.error)

    def software_rollback(self, sw_slot_id, timeout=10, **kwargs):
        resp = self._client.send(
            method='software.rollback',
            timeout=timeout,
            parameters={"slotId": str(sw_slot_id)})
        if resp.status is False:
            raise OperationFailure(resp.error)

    def _is_hash_containter_related(self, next_filename):
        hash_container_related = ("HashContainer", "HashContainerSignature")
        if any(name in next_filename for name in hash_container_related):
            return True

        return False

    def _send_security_files(self, activation_status, timeout):

        next_filename = activation_status.next_filename

        while not self._check_if_sw_already_installed(activation_status):
            if not self._is_hash_containter_related(next_filename):
                msg = 'Instead of activating desired software partition, OAM asked for more files. ' \
                      'This means that software version on desired partition is not consistent.'
                raise OperationFailure(msg)

            resp = self.upload_a_file(
                next_file_name=next_filename, package=self.last_package, timeout=timeout)

            if resp.status is False:
                raise OperationFailure(resp.status)

            activation_status = SoftwareUpdateStatus.from_object_dict(resp.data)

            next_filename = activation_status.next_filename

    def clear_sw_update_cache(self):
        self.last_targetBD = None
        self.last_updated_sw_slot_id = None
        self.last_package = None


class Package():
    ROOT_DIR_REGEX = r"^bts\_sw\/$"

    def __init__(self, archive):
        self._zip = zipfile.ZipFile(archive, 'r')
        self._root_dir = self.get_root_dir()

    def get_root_dir(self):
        """ Looks for root_dir bts_sw """
        file_list = self._zip.namelist()
        if any(re.match(self.ROOT_DIR_REGEX, file_name) for file_name in file_list):
            return "bts_sw"
        else:
            raise RootDirNotFound("Root dir 'bts_sw' has not been found in target package")

    def find_filepaths(self, name):
        """ find filepaths containing name"""
        files = [filename for filename in self._zip.namelist() if name in filename]
        return files

    def read_file(self, file_name):
        if not file_name.startswith(self._root_dir):
            file_path_format = "{root_name}{leading_slash}{file_path}"
            leading_slash = '' if file_name.startswith('/') else '/'
            file_name = file_path_format.format(root_name=self._root_dir,
                                                leading_slash=leading_slash,
                                                file_path=file_name)
        try:
            return self._zip.read(file_name)
        except KeyError as exc:
            raise OperationFailure(exc)
